//! The QEMU crossing (feature `qemu-guest`, QEMU bridge plan Q4): the guest is aarch64 under QEMU's user-mode TCG, so a crossing is an `svc` trap, not a thread-pointer switch. The seam's second implementation; `x86_64.rs` is the first, and the names and contracts match.
//! A binding thunk is two words, `svc #(BIND | id)` then `ret`. The pool (`pool`, generated by build.rs through atl-bridgegen) holds slot k = thunk k, page aligned in `.rodata`. `bind` hands out slots; `patch_site` and `patch_hook` copy a slot's words over a placeholder (`mov x3,#0; blr x3`) of the guest image; [`on_trap`] calls the host target of a binding trap.
//! Q4-2 makes binding, placeholder recognition, the in-place writes and the trap route real. Q4-3 places the vdso entries in their bodies (`patch_entry`, the body found by shape), and registers the pool and the images with QEMU (`register`). The start sequence (`set_bootstrap`, `call_guest`, `init_tcb`, the BOOT trap) and the JNI stubs are Q4-4 to Q5 and abort (`unsupported`) until their slice lands.

use std::sync::atomic::{AtomicUsize, Ordering};

use atl_qemu_engine::{Guest, Trap, page};

use super::bindings::THUNKS;
use super::image::{Image, write_sealed};
use super::unsupported;

/// Generated by build.rs (`aarch64_pool.rs`): the thunk constants (`PLACEHOLDER`), and `POOL`, slot k = `svc #(BIND | k); ret`.
#[allow(
    clippy::all,
    dead_code,
    reason = "generated by atl-bridgegen (aarch64::constants_rust, aarch64::pool_rust)"
)]
mod pool {
    include!(concat!(env!("OUT_DIR"), "/aarch64_pool.rs"));
}

/// Bytes per thunk: two instruction words.
const THUNK_BYTES: usize = 8;
/// The host target of each pool slot, read by [`call_binding`].
static TARGETS: [AtomicUsize; THUNKS] = [const { AtomicUsize::new(0) }; THUNKS];
/// Next free pool slot.
static NEXT: AtomicUsize = AtomicUsize::new(0);

// one generated slot per binding: the pool and the table are sized by the same build-time count
const _: () = assert!(std::mem::size_of::<pool::Pool>() == THUNKS * THUNK_BYTES);

/// JNI table slots, as the x86 engine (`JNINativeInterface` has 233). The QEMU JNI stubs come with the JNI slice (Q5).
pub const JNI_STUBS: usize = 256;

/// The crossing record of a thread. The QEMU thread pointer lives in the engine's CPU state, so the record holds only the guest thread pointer that thread.rs reads and writes.
pub struct HostThread {
    guest_fs: usize,
}

impl HostThread {
    /// A record for the calling thread; leaked, as the x86 record is: it lives for the thread.
    pub fn leak() -> &'static mut HostThread {
        Box::leak(Box::new(HostThread { guest_fs: 0 }))
    }

    /// The guest thread pointer the crossing last saw (0 before the first).
    pub fn guest_fs(&self) -> usize {
        self.guest_fs
    }

    /// Sets the guest thread pointer the next crossing installs.
    pub fn set_guest_fs(&mut self, v: usize) {
        self.guest_fs = v;
    }
}

/// Whether the crossing is available: QEMU's user-mode core needs no thread-pointer feature.
pub fn supported() -> bool {
    true
}

/// The bootstrap record of the x86 crossing, set while the guest linker runs `__linker_init`. QEMU's start sequence replays that host-side (Q4-4), so this aborts until then.
pub fn set_bootstrap(_ht: Option<*mut HostThread>) {
    unsupported("qemu crossing: Guest::start (set_bootstrap) lands in Q4-4")
}

/// Initialises the guest TCB `tp` for record `ht` (x86: the native-bridge slot). Aborts until the QEMU start sequence lands (Q4-4).
///
/// # Safety
/// As the x86 seam's: `tp` is a guest TCB, live while `ht` is used on it.
pub unsafe fn init_tcb(_tp: usize, _ht: *mut HostThread) {
    unsupported("qemu crossing: the guest TCB lands in Q4-4 (init_tcb)")
}

/// Calls guest `f(a, b, c, d)` on the thread's guest state. Aborts until `Guest::call` of the QEMU engine is wired (Q4-4).
///
/// # Safety
/// As the x86 seam's: `f` is guest code with up to four integer arguments.
pub unsafe fn call_guest(
    _ht: &mut HostThread,
    _f: usize,
    _a: usize,
    _b: usize,
    _c: usize,
    _d: usize,
) -> usize {
    unsupported("qemu crossing: call_guest lands in Q4-4 (Guest::call)")
}

/// A guest-callable address that crosses to host function `target`: the address of a free pool slot, which [`on_trap`] routes to `target`. None when the pool is used up.
pub fn bind(target: usize) -> Option<usize> {
    let slot = NEXT.fetch_add(1, Ordering::Relaxed);
    if slot >= THUNKS {
        return None;
    }
    TARGETS[slot].store(target, Ordering::Release);
    Some((&raw const pool::POOL) as usize + slot * THUNK_BYTES)
}

/// The guest-callable address of JNI table slot `slot`. Aborts until the QEMU JNI stubs land (Q5).
pub fn jni_stub(_slot: usize) -> usize {
    unsupported("qemu crossing: JNI stubs land in Q5")
}

/// The two instruction words at `addr`.
fn read_words(addr: usize) -> [u32; 2] {
    // SAFETY: `addr` is an instruction site of a guest image the engine mapped, or a stub the guest passed to `native_bridge_intercept_symbol`; its 8 bytes are readable.
    unsafe { (addr as *const [u32; 2]).read_unaligned() }
}

/// The 8-byte placeholder of an unbound stub: `ldr x3, =0; blr x3`, assembled to `mov x3, #0; blr x3`.
#[cfg(not(atl_nb_qe_prefix))]
pub fn is_stub(addr: usize) -> bool {
    read_words(addr) == pool::PLACEHOLDER
}

/// Deliberate break of the placeholder shape check (`ATL_NB_BREAK=qe_prefix`): only the first two bytes decide, so a site whose tail differs is taken for a stub.
#[cfg(atl_nb_qe_prefix)]
pub fn is_stub(addr: usize) -> bool {
    read_words(addr)[0] & 0xffff == pool::PLACEHOLDER[0] & 0xffff
}

/// The words of the pool slot at address `thunk` (from `bind`); None when `thunk` is no slot.
fn slot_words(thunk: usize) -> Option<[u32; 2]> {
    let base = &raw const pool::POOL as usize;
    let slot = thunk.checked_sub(base)? / THUNK_BYTES;
    pool::POOL.0.get(slot).copied()
}

/// Two instruction words as AArch64 stores them: little-endian, first word first.
fn word_bytes(words: [u32; 2]) -> [u8; THUNK_BYTES] {
    let mut out = [0u8; THUNK_BYTES];
    out[..4].copy_from_slice(&words[0].to_le_bytes());
    out[4..].copy_from_slice(&words[1].to_le_bytes());
    out
}

/// Replaces the stub at `addr` (`is_stub`) with the thunk `thunk` (from `bind`), in sealed guest text. False when `addr` is no stub or `thunk` is no pool slot.
pub fn patch_site(addr: usize, thunk: usize) -> bool {
    if !is_stub(addr) {
        return false;
    }
    let Some(words) = slot_words(thunk) else {
        return false;
    };
    write_sealed(addr, &word_bytes(words));
    true
}

/// Writes the thunk `words` over the placeholder at `at`, in an image still writable (before `seal`).
fn write_before_seal(at: usize, words: [u32; 2]) {
    // SAFETY: `at` is an 8-byte placeholder the caller found with `is_stub` in a segment it mapped and has not sealed.
    unsafe {
        std::ptr::copy_nonoverlapping(word_bytes(words).as_ptr(), at as *mut u8, THUNK_BYTES)
    };
}

/// Routes the linker hook at `at` (its placeholder, before `seal`) to a thunk of `host`.
pub fn patch_hook(at: usize, host: usize) -> Result<(), &'static str> {
    if !is_stub(at) {
        return Err("not the 8-byte placeholder this engine rewrites");
    }
    let thunk = bind(host).ok_or("out of thunks")?;
    let words = slot_words(thunk).ok_or("bound thunk is no pool slot")?;
    write_before_seal(at, words);
    Ok(())
}

/// Bytes of a vdso entry's body that may hold its placeholder: `nop; nop; ldr x3, =0; blr x3` (NBS vdso_arm64.S:50-54), the longest.
/// Break `qe_site` shortens it to the symbol's own 8 bytes, so `native_bridge_call_guest` (placeholder at +8) is not found.
#[cfg(not(atl_nb_qe_site))]
const ENTRY_BODY_BYTES: usize = 16;
#[cfg(atl_nb_qe_site)]
const ENTRY_BODY_BYTES: usize = THUNK_BYTES;
/// Placeholders sit on instruction-word boundaries.
const WORD_BYTES: usize = 4;

/// The `st_value` of a .dynsym entry (`Image::dynsym_values`'s address): the symbol's address before the load bias.
fn st_value(value_at: usize) -> usize {
    // SAFETY: `value_at` is the st_value field of a .dynsym entry of an image this engine mapped and has not sealed (`Image::dynsym_values`), 8 readable bytes.
    unsafe { (value_at as *const usize).read_unaligned() }
}

/// The one placeholder whose 8 bytes lie in `[start, end)`, on a word boundary. Absent or more than one is an error: a vdso that differs from the pin fails closed.
fn find_placeholder(start: usize, end: usize) -> Result<usize, &'static str> {
    let mut found = None;
    let mut at = start;
    while at + THUNK_BYTES <= end {
        if is_stub(at) && found.replace(at).is_some() {
            return Err("two placeholders in the entry's body");
        }
        at += WORD_BYTES;
    }
    found.ok_or("no placeholder in the entry's body")
}

/// Routes the vdso entry whose st_value field is at `value_at` to a host function (before `seal`). Its placeholder is searched in the entry's body: from the symbol up to the next dynamic symbol, at most [`ENTRY_BODY_BYTES`]. Symbols carry no size here (asm symbols, size 0), so the next symbol is the bound.
pub fn patch_entry(vdso: &Image, value_at: usize, host: usize) -> Result<(), &'static str> {
    let start = vdso.bias + st_value(value_at);
    let next = vdso
        .dynsym_values()
        .iter()
        .map(|&(_, at)| vdso.bias + st_value(at))
        .filter(|&addr| addr > start)
        .min()
        .unwrap_or(usize::MAX);
    let at = find_placeholder(start, next.min(start + ENTRY_BODY_BYTES))?;
    let thunk = bind(host).ok_or("out of thunks")?;
    let words = slot_words(thunk).ok_or("bound thunk is no pool slot")?;
    write_before_seal(at, words);
    Ok(())
}

/// QEMU page flags of a segment's `PROT_*`: each bit the ELF segment declares.
fn qemu_flags(prot: i32) -> i32 {
    let bit = |prot_bit: i32, page_bit: i32| if prot & prot_bit != 0 { page_bit } else { 0 };
    bit(libc::PROT_READ, page::READ)
        | bit(libc::PROT_WRITE, page::WRITE)
        | bit(libc::PROT_EXEC, page::EXEC)
}

/// Registers the host pool (executable) and every segment of `images` with QEMU, identity mapped, so a guest fetch from them does not fault. Call from a trap, before the first guest fetch from them; `Guest::map_pages` checks the range.
/// Break `qe_nomap` skips it: a guest fetch from a placed site then faults.
#[cfg(not(atl_nb_qe_nomap))]
pub fn register(g: &Guest, images: &[&Image]) -> Result<(), String> {
    let pool_start = (&raw const pool::POOL) as usize;
    g.map_pages(
        pool_start,
        std::mem::size_of::<pool::Pool>(),
        page::READ | page::EXEC,
    )?;
    for image in images {
        for &(start, len, prot) in image.segments() {
            g.map_pages(start, len, qemu_flags(prot))?;
        }
    }
    Ok(())
}

/// Break `qe_nomap` (see [`register`]): no page is registered.
#[cfg(atl_nb_qe_nomap)]
pub fn register(_g: &Guest, _images: &[&Image]) -> Result<(), String> {
    Ok(())
}

/// The engine's `OnTrap` for this crossing: a binding trap calls the host target of its slot and answers with its result (the guest's x0). Other traps are the engine's own protocol (BOOT: Q4-4; call, report, thread: later) and abort here until their slice routes them.
pub fn on_trap(_g: Guest, trap: Trap) -> u64 {
    match trap {
        Trap::Bind { id, args } => call_binding(id, args),
        Trap::Boot(_) => unsupported("qemu crossing: BOOT (Guest::start) lands in Q4-4"),
        other => unsupported(&format!("qemu crossing: {other:?} is not routed yet")),
    }
}

/// Calls the host function of slot `id` with the guest's eight integer argument words. Integer arguments only: floats (v0..v7) are Q6. A callee with fewer arguments ignores the rest, under AAPCS64 and SysV alike.
fn call_binding(id: u32, args: [u64; 8]) -> u64 {
    let Some(slot) = usize::try_from(id).ok().and_then(|i| TARGETS.get(i)) else {
        unsupported("qemu crossing: binding id past the pool")
    };
    let target = slot.load(Ordering::Acquire);
    if target == 0 {
        unsupported("qemu crossing: binding trap for an unbound slot")
    }
    type Host = extern "C" fn(u64, u64, u64, u64, u64, u64, u64, u64) -> u64;
    // SAFETY: `target` is the host function `bind` stored for this slot, a pointer to a C-ABI function that takes integer arguments only; the call passes it the guest's argument words.
    let host: Host = unsafe { std::mem::transmute::<usize, Host>(target) };
    let [a0, a1, a2, a3, a4, a5, a6, a7] = args;
    host(a0, a1, a2, a3, a4, a5, a6, a7)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A binding trap runs the host function of its slot with the eight argument words and answers with its result.
    #[test]
    fn binding_trap_calls_its_target() {
        extern "C" fn target(
            a: u64,
            _: u64,
            _: u64,
            _: u64,
            _: u64,
            _: u64,
            _: u64,
            h: u64,
        ) -> u64 {
            a * 100 + h
        }
        let thunk = bind(target as *const () as usize).expect("a free pool slot");
        let base = &raw const pool::POOL as usize;
        let id = u32::try_from((thunk - base) / THUNK_BYTES).expect("slot fits an id");
        // a * 100 + h with a = 1, h = 8
        assert_eq!(call_binding(id, [1, 2, 3, 4, 5, 6, 7, 8]), 108);
    }

    /// The placeholder is the stub; a site with the same first two bytes but another tail (`br x3`) is not. Break `qe_prefix` takes it for one.
    #[test]
    fn stub_shape_is_the_whole_placeholder() {
        let placeholder: [u32; 2] = pool::PLACEHOLDER;
        // br x3 = d61f0060 (ARM ARM): the placeholder's `mov x3, #0` word, another second word
        let br: [u32; 2] = [placeholder[0], 0xD61F_0060];
        assert!(is_stub(placeholder.as_ptr() as usize));
        assert!(!is_stub(br.as_ptr() as usize));
    }

    /// An entry body holds exactly one placeholder: the search finds it at its word offset, and fails closed on none or two. The words are ARM ARM literals: `nop` d503201f, `mov x3, #0` d2800003, `blr x3` d63f0060.
    #[test]
    fn entry_body_holds_one_placeholder() {
        const NOP: u32 = 0xD503_201F;
        const MOV_X3_0: u32 = 0xD280_0003;
        const BLR_X3: u32 = 0xD63F_0060;
        // nop, nop, placeholder: the placeholder at byte 8 (vdso_arm64.S native_bridge_call_guest)
        let body: [u32; 4] = [NOP, NOP, MOV_X3_0, BLR_X3];
        let base = body.as_ptr() as usize;
        assert_eq!(find_placeholder(base, base + 16), Ok(base + 8));
        // the range ends before the placeholder: none
        assert!(find_placeholder(base, base + 8).is_err());
        // two placeholders in one range: ambiguous
        let two: [u32; 4] = [MOV_X3_0, BLR_X3, MOV_X3_0, BLR_X3];
        let base2 = two.as_ptr() as usize;
        assert!(find_placeholder(base2, base2 + 16).is_err());
    }
}
